```python
def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Invalid duration string")

    total = 0
    current_num = []
    unit_multipliers = {'h': 3600, 'm': 60, 's': 1}
    used_units = set()

    for char in s:
        if char.isdigit():
            current_num.append(char)
        elif char in unit_multipliers:
            if not current_num:
                raise ValueError("Invalid duration string")
            total += int(''.join(current_num)) * unit_multipliers[char]
            used_units.add(char)
            current_num = []
        else:
            raise ValueError("Invalid duration string")

    if current_num:
        raise ValueError("Invalid duration string")

    return total
```

```python
def split_csv_line(line: str) -> list[str]:
    fields = []
    current_field = []
    in_quotes = False
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if in_quotes:
            if c == '"':
                if i + 1 < n and line[i+1] == '"':
                    current_field.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                current_field.append(c)
            i += 1
        else:
            if c == '"':
                in_quotes = True
            elif c == ',':
                fields.append(''.join(current_field))
                current_field = []
            else:
                current_field.append(c)
            i += 1
    fields.append(''.join(current_field))
    return fields
```

```python
def parse_headers(raw: str) -> dict[str, str]:
    headers = {}
    for line in raw.replace('\r\n', '\n').split('\n'):
        if not line.strip():
            continue
        if ':' not in line:
            raise ValueError("Header lines must contain a colon")
        name, value = line.split(':', 1)
        key = name.strip().lower()
        val = value.strip()
        if key in headers:
            headers[key] += ', ' + val
        else:
            headers[key] = val
    return headers
```

```python
def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    from decimal import Decimal, ROUND_HALF_UP

    for scale, unit in [(1_000_000_000, 'bi'), (1_000_000, 'mi'), (1_000, 'mil')]:
        val = Decimal(n) / Decimal(scale)
        rounded = val.quantize(Decimal('0.1'), rounding=ROUND_HALF_UP)
        if 1 <= rounded < 1000:
            formatted = str(rounded).replace('.', ',')
            if formatted.endswith(',0'):
                formatted = formatted[:-2]
            return f"{formatted} {unit}"

    # Fallback for n >= 1 trillion (extends pattern if needed)
    scale, unit = 1_000_000_000_000, 'tril'
    val = Decimal(n) / Decimal(scale)
    rounded = val.quantize(Decimal('0.1'), rounding=ROUND_HALF_UP)
    formatted = str(rounded).replace('.', ',')
    if formatted.endswith(',0'):
        formatted = formatted[:-2]
    return f"{formatted} {unit}"
