```python
def allocate(total_cents: int, weights: list[int]) -> list[int]:
    if total_cents < 0:
        raise ValueError("total_cents cannot be negative")
    if not weights:
        raise ValueError("weights cannot be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    total_weight = sum(weights)
    if total_weight == 0:
        raise ValueError("all weights cannot be zero")

    base = [(total_cents * w) // total_weight for w in weights]
    remainders = [(total_cents * w) % total_weight for w in weights]
    leftover = total_cents - sum(base)

    allocation = base.copy()
    indices_sorted = sorted(range(len(weights)), key=lambda i: (-remainders[i], i))
    for k in range(leftover):
        allocation[indices_sorted[k]] += 1

    return allocation
```

```python
def add_business_days(d: date, n: int, holidays: set[date]) -> date:
    if n == 0:
        if d.weekday() < 5 and d not in holidays:
            return d
        while True:
            d += timedelta(days=1)
            if d.weekday() < 5 and d not in holidays:
                return d

    direction = 1 if n > 0 else -1
    while n != 0:
        d += timedelta(days=direction)
        if d.weekday() < 5 and d not in holidays:
            n -= direction
    return d
```

