import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all unique nodes from both keys (items) and values (dependencies)
    nodes = set()
    for item in deps:
        nodes.add(item)
        nodes.update(deps[item])

    if not nodes:
        return []

    # Build the graph. Since A depends on B, we have a directed edge B -> A.
    # We need an adjacency list for outgoing edges and an in-degree count for each node.
    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for item, dependencies in deps.items():
        for dep in dependencies:
            # Edge from dependency (dep) to dependent (item)
            # Note: 'dep' is guaranteed to be in 'nodes' because we added all values.
            adj[dep].append(item)
            in_degree[item] += 1

    # Initialize the priority queue with nodes that have no dependencies (in-degree 0).
    # Using a min-heap ensures we pick the alphabetically smallest item first among available ones.
    pq = []
    for node in nodes:
        if in_degree[node] == 0:
            heapq.heappush(pq, node)

    result = []

    while pq:
        current = heapq.heappop(pq)
        result.append(current)

        # Decrease in-degree of neighbors. If a neighbor becomes ready (in-degree 0), push to heap.
        for neighbor in adj[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(pq, neighbor)

    # If the result does not contain all nodes, there is a cycle in the graph.
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
