import unicodedata

def sort_names(names: list[str]) -> list[str]:
    def key_func(name):
        norm = ''.join(c for c in unicodedata.normalize('NFD', name) if unicodedata.category(c) != 'Mn').lower()
        return (norm, norm != name.lower(), name)
    return sorted(names, key=key_func)
