def deep_merge(base: dict, override: dict) -> dict:
    def _copy(val):
        if isinstance(val, dict):
            return {k: _copy(v) for k, v in val.items()}
        elif isinstance(val, list):
            return [_copy(item) for item in val]
        return val

    result = {}
    all_keys = list(base.keys())
    for key in override:
        if key not in base:
            all_keys.append(key)

    for key in all_keys:
        if key in override:
            o_val = override[key]
            if o_val is None:
                continue

            if key in base and isinstance(o_val, dict) and isinstance(base[key], dict):
                result[key] = deep_merge(base[key], o_val)
            else:
                result[key] = _copy(o_val)
        else:
            result[key] = _copy(base[key])

    return result
```

