import re
from decimal import Decimal

def parse_brl(s: str) -> Decimal:
    s = s.strip()
    if not s:
        raise ValueError("Empty string")

    neg = False
    if s.startswith('(') and s.endswith(')'):
        neg = True
        s = s[1:-1].strip()
    if s.startswith('-'):
        neg = True
        s = s[1:].strip()

    s = re.sub(r'^\s*R\$\s*', '', s).strip()
    if not s:
        raise ValueError("Invalid format")

    if ',' in s:
        idx = s.rfind(',')
        int_part = s[:idx]
        dec_part = s[idx+1:]
        if not dec_part.isdigit() or len(dec_part) != 2:
            raise ValueError("Invalid decimal part")
    else:
        int_part = s
        dec_part = '00'

    if not int_part:
        int_part = '0'
    elif '.' in int_part:
        parts = int_part.split('.')
        for i, p in enumerate(parts):
            if not p.isdigit():
                raise ValueError("Invalid characters in integer part")
            if i == 0:
                if len(p) < 1 or len(p) > 3:
                    raise ValueError("Invalid integer part grouping")
            else:
                if len(p) != 3:
                    raise ValueError("Invalid thousand separator grouping")
        int_part = ''.join(parts)
    elif not int_part.isdigit():
        raise ValueError("Invalid characters in integer part")

    val_str = f"{int_part}.{dec_part}"
    res = Decimal(val_str)
    if neg:
        res = -res
    return res
```

