def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    chunks = []
    for word in words:
        if len(word) > width:
            i = 0
            while i < len(word):
                chunks.append(word[i:i+width])
                i += width
        else:
            chunks.append(word)

    lines = []
    current_line = []
    current_len = 0

    for chunk in chunks:
        cl = len(chunk)
        if not current_line or current_len + 1 + cl > width:
            if current_line:
                lines.append(" ".join(current_line))
            current_line = [chunk]
            current_len = cl
        else:
            current_line.append(chunk)
            current_len += 1 + cl

    if current_line:
        lines.append(" ".join(current_line))

    return lines
