```python
def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines(keepends=True)
    current_section = None
    section_found = False
    key_found = False
    new_lines = []

    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith((';', '#')):
            new_lines.append(line)
            continue
        if stripped.startswith('['):
            sec_name = stripped[1:].split(']')[0].strip()
            if sec_name == section:
                section_found = True
            current_section = sec_name
            new_lines.append(line)
            continue
        if '=' in stripped:
            k, _ = stripped.split('=', 1)
            if current_section == section and k.strip() == key:
                end = line[len(line.rstrip('\r\n')):]
                new_lines.append(f"{key} = {value}{end}")
                key_found = True
            else:
                new_lines.append(line)
        else:
            new_lines.append(line)

    if not section_found or not key_found:
        raise KeyError(f"Section '{section}' or key '{key}' not found")
    return ''.join(new_lines)
