def split_csv_line(line: str) -> list[str]:
    fields = []
    current_field = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        char = line[i]
        if not in_quotes:
            if char == '"':
                in_quotes = True
            elif char == ',':
                fields.append(''.join(current_field))
                current_field = []
            else:
                current_field.append(char)
        else:
