def allocate(total_cents: int, weights: list[int]) -> list[int]:
    if total_cents < 0:
        raise ValueError("total_cents must be non-negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    if sum(weights) == 0:
        raise ValueError("all weights are zero")

    total_weight = sum(weights)
    base = [w * total_cents // total_weight for w in weights]
    remainder_count = total_cents - sum(base)

    sorted_indices = sorted(
        range(len(weights)),
        key=lambda i: (-(weights[i] * total_cents % total_weight), i)
    )

    result = base.copy()
    for i in range(remainder_count):
        result[sorted_indices[i]] += 1

    return result
