def wrap(text: str, width: int) -> list[str]:
    lines = []
    current_line = []
    current_len = 0
    for word in text.split():
        if len(word) > width:
            chunks = [word[i:i+width] for i in range(0, len(word), width)]
        else:
            chunks = [word]

        for chunk in chunks:
            space_needed = 1 if current_line else 0
            if current_len + space_needed + len(chunk) > width:
                lines.append(" ".join(current_line))
                current_line = []
                current_len = 0
                space_needed = 0

            current_line.append(chunk)
            current_len += space_needed + len(chunk)

    if current_line:
        lines.append(" ".join(current_line))
    return lines
