def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines(True)
    current_section = None
    section_found = False
    key_found = False
    result = []

    for line in lines:
        stripped = line.strip()

        if stripped.startswith('[') and ']' in stripped:
            sec_name = stripped[1:].split(']', 1)[0].strip()
            if sec_name == section:
                current_section = section
                section_found = True
            elif current_section == section:
                current_section = None

        if current_section == section and stripped and not stripped.startswith('#') and not stripped.startswith(';'):
            if '=' in stripped:
                k, _, _ = stripped.partition('=')
                if k.strip() == key:
                    trailing = line[len(line.rstrip('\r\n')):]
                    result.append(f"{key} = {value}" + (trailing if trailing else "\n"))
                    key_found = True
                    continue

        result.append(line)

    if not section_found or not key_found:
        raise KeyError("Section or key not found")
    return ''.join(result)
