```python
def remove_Occ(s, ch):
    first = s.find(ch)
    if first == -1:
        return s
    last = s.rfind(ch)
    if first == last:
        return s[:first] + s[first+1:]
    return s[:first] + s[first+1:last] + s[last+1:]
```

```python
def is_woodall(n):
    if n < 1:
        return False
    k = 1
    while True:
        val = k * (2 ** k) - 1
        if val == n:
            return True
        if val > n:
            return False
        k += 1
